375     //  Decoding of the request in stage 0
376     //  {{{
377     always_comb
378     begin : st0_req_pma_comb
379         st0_req_pma = core_req_i.pma;
380 
381         //  force uncacheable requests if the cache is disabled
382         if (!cfg_enable_i) begin
383             st0_req_pma.uncacheable = 1'b1;
384         end
385 
386         //  if either WB or WT is not supported, force write-policy
387         if (!HPDcacheCfg.u.wtEn) begin
388             st0_req_pma.wr_policy_hint = HPDCACHE_WR_POLICY_WB;
389         end
390         if (!HPDcacheCfg.u.wbEn) begin
391             st0_req_pma.wr_policy_hint = HPDCACHE_WR_POLICY_WT;
392         end
393     end
394 
395     //     Select between request in the replay table or a new core requests
396     assign st0_req.addr_offset  = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.addr_offset
397                                                          : core_req_i.addr_offset;
398     assign st0_req.addr_tag     = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.addr_tag
399                                                          : core_req_i.addr_tag;
400     assign st0_req.wdata        = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.wdata
401                                                          : core_req_i.wdata;
402     assign st0_req.op           = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.op
403                                                          : core_req_i.op;
404     assign st0_req.be           = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.be
405                                                          : core_req_i.be;
406     assign st0_req.size         = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.size
407                                                          : core_req_i.size;
408     assign st0_req.sid          = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.sid
409                                                          : core_req_i.sid;
410     assign st0_req.tid          = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.tid
411                                                          : core_req_i.tid;
412     assign st0_req.need_rsp     = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.need_rsp
413                                                          : core_req_i.need_rsp;
414     assign st0_req.phys_indexed = st0_rtab_pop_try_valid ? 1'b1 :
415                                                            core_req_i.phys_indexed;
416     assign st0_req.pma          = st0_rtab_pop_try_valid ? st0_rtab_pop_try_req.req.pma
417                                                          : st0_req_pma;
418 
419     //     Check if the request from the RTAB has been tagged with an error
420     assign st0_req_is_error = st0_rtab_pop_try_valid & st0_rtab_pop_try_error;
421 
422     //     Decode operation in stage 0
423     assign st0_req_is_uncacheable  =     st0_req.pma.uncacheable;
424     assign st0_req_is_load         =         is_load(st0_req.op);
425     assign st0_req_is_store        =        is_store(st0_req.op);
426     assign st0_req_is_amo          =          is_amo(st0_req.op);
427     assign st0_req_is_cmo_fence    =    is_cmo_fence(st0_req.op);
428     assign st0_req_is_cmo_inval    =    is_cmo_inval(st0_req.op);
429     assign st0_req_is_cmo_prefetch = is_cmo_prefetch(st0_req.op);
430     //  }}}
431 
432     //  Decode operation in stage 1
433     //  {{{
434     always_comb
435     begin : st1_req_pma_comb
436         st1_req_pma = st1_req_q.phys_indexed ? st1_req_q.pma : core_req_pma_i;
437 
438         //  force uncacheable requests if the cache is disabled
439         if (!cfg_enable_i) begin
440             st1_req_pma.uncacheable = 1'b1;
441         end
442 
443         //  if either WB or WT is not supported, force write-policy
444         if (!HPDcacheCfg.u.wtEn) begin
445             st1_req_pma.wr_policy_hint = HPDCACHE_WR_POLICY_WB;
446         end
447         if (!HPDcacheCfg.u.wbEn) begin
448             st1_req_pma.wr_policy_hint = HPDCACHE_WR_POLICY_WT;
449         end
450     end
451 
452     //         In case of replay or physically-indexed cache, the tag and PMA come
453     //         from stage 0. Otherwise, this information come directly from the
454     //         requester in stage 1
455     assign st1_req_tag = st1_req_q.phys_indexed ? st1_req_q.addr_tag : core_req_tag_i;
456 
457     assign st1_req.addr_offset     = st1_req_q.addr_offset;
458     assign st1_req.addr_tag        = st1_req_rtab_q ? st1_req_q.addr_tag : st1_req_tag;
459     assign st1_req.wdata           = st1_req_q.wdata;
460     assign st1_req.op              = st1_req_q.op;
461     assign st1_req.be              = st1_req_q.be;
462     assign st1_req.size            = st1_req_q.size;
463     assign st1_req.sid             = st1_req_q.sid;
464     assign st1_req.tid             = st1_req_q.tid;
465     assign st1_req.need_rsp        = st1_req_q.need_rsp;
466     assign st1_req.phys_indexed    = st1_req_q.phys_indexed;
