1037             $onehot0({core_req_ready_o, st0_rtab_pop_try_ready, refill_req_ready_o})) else
1038                     $error("ctrl: only one request can be served per cycle");
1039 
1040     //  Check that requests have a valid size field. The check is not necessary for the fence,
1041     //  invalidation and flush CMOs because these requests do not use the size field.
1042     property prop_core_req_size_max;
1043         @(posedge clk_i) disable iff (!rst_ni) (
1044             core_req_valid_i && core_req_ready_o &&
1045             !(is_cmo_fence(core_req_i.op) ||
1046               is_cmo_inval(core_req_i.op) ||
1047               is_cmo_flush(core_req_i.op))
1048         ) |-> (
1049             (2**core_req_i.size) <= HPDcacheCfg.reqDataBytes
1050         );
1051     endproperty
1052 
1053     assert property (prop_core_req_size_max) else
1054             $error("ctrl: bad SIZE for request");
1055 
1056     //  Check that stores and AMOs requests have a valid Byte Enable field. In particular, check
1057     //  that it is aligned with respect to the address
1058     function automatic bit check_is_be_aligned(
1059       input hpdcache_req_offset_t req_offset,
1060       input hpdcache_req_be_t req_be
1061     );
1062         int offset = int'(req_offset) % HPDcacheCfg.reqDataBytes;
1063         return (((req_be >> offset) << offset) == req_be);
1064     endfunction
1065 
1066     property prop_core_req_be_align;
1067         @(posedge clk_i) disable iff (!rst_ni) (
1068             core_req_valid_i && core_req_ready_o &&
1069             (is_store(core_req_i.op) || is_amo(core_req_i.op))
1070         ) |-> (
1071             check_is_be_aligned(core_req_i.addr_offset, core_req_i.be)
1072         );
1073     endproperty
1074 
1075     assert property (prop_core_req_be_align) else
1076             $error("ctrl: bad BE alignment for request");
